import{_ as e,o as r,c as i,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Configuración general","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/general.md","filePath":"es-ES/user-guide/settings/general.md","lastUpdated":1787586465000}'),n={name:"es-ES/user-guide/settings/general.md"};function s(t,a,d,l,c,p){return r(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="configuracion-general" tabindex="-1">Configuración general <a class="header-anchor" href="#configuracion-general" aria-label="Permalink to &quot;Configuración general&quot;">​</a></h1><p>Configuración general abarca el comportamiento central del sistema, las dimensiones y el diseño visual de las ventanas de búsqueda, la ponderación de prioridad de los tipos de resultados y el orden de los proveedores de vista previa. La página se divide en seis pestañas superiores: <strong>Sistema</strong>, <strong>Ventana de búsqueda rápida</strong>, <strong>Ventana de búsqueda principal</strong>, <strong>Ventana de vista previa</strong>, <strong>Navegación rápida</strong> y <strong>Vista previa y miniaturas</strong>.</p><h2 id="_1-sistema" tabindex="-1">1. Sistema <a class="header-anchor" href="#_1-sistema" aria-label="Permalink to &quot;1. Sistema&quot;">​</a></h2><ul><li><strong>Iniciar Lertaro al arrancar el sistema</strong>: Inicia Lertaro automáticamente al iniciar sesión en Windows.</li><li><strong>Buscar actualizaciones al iniciar</strong>: Comprueba automáticamente en línea si hay nuevas versiones al abrir la aplicación.</li><li><strong>Actualizaciones silenciosas</strong>: Solo disponible cuando &quot;Buscar actualizaciones&quot; está activo. Descarga e instala actualizaciones en segundo plano sin cuadros de diálogo molestos.</li><li><strong>Habilitar aceleración por hardware</strong>: Activado por defecto. Si tu portátil con doble GPU (como NVIDIA Advanced Optimus) no cambia de gráfica por la presencia de Lertaro, desactívalo para usar renderizado por software. Requiere reiniciar Lertaro.</li><li><strong>Ocultar icono de la bandeja del sistema</strong>: Oculta el icono del área de notificación. El logotipo dentro de la barra de búsqueda rápida sigue desplegando el menú completo de la bandeja.</li><li><strong>Habilitar servicio de compatibilidad Everything (IPC)</strong>: Emula el protocolo Win32 IPC de Everything para que Directory Opus, Total Commander y otras herramientas consulten el índice en memoria de Lertaro directamente.</li><li><strong>Habilitar coincidencia difusa</strong>: Activado por defecto. Permite coincidencias no consecutivas; si se desactiva, solo coincidirán subcadenas continuas (ver <a href="./../search-syntax.html"><strong>Sintaxis de búsqueda</strong></a>). Surte efecto inmediato.</li><li><strong>Delimitador de tokens de consulta</strong>: Campo de un solo carácter (por defecto <code>:</code>). Define el prefijo para los tokens de sufijo (p. ej. <code>:.pdf</code>, <code>:@doc</code>, <code>:[S]</code>).</li><li><strong>Nivel de registro</strong>: Selecciona Error / Advertencia / Información (predeterminado) / Depuración para la verbosidad de los registros.</li><li><strong>Idioma de la interfaz</strong>: Selecciona el idioma global de la aplicación.</li></ul><h2 id="_2-ventana-de-busqueda-rapida" tabindex="-1">2. Ventana de búsqueda rápida <a class="header-anchor" href="#_2-ventana-de-busqueda-rapida" aria-label="Permalink to &quot;2. Ventana de búsqueda rápida&quot;">​</a></h2><p>Permite ajustar con precisión las dimensiones geométricas y las prioridades de la barra flotante centrada:</p><h3 id="diseno-de-la-barra-de-busqueda" tabindex="-1">Diseño de la barra de búsqueda <a class="header-anchor" href="#diseno-de-la-barra-de-busqueda" aria-label="Permalink to &quot;Diseño de la barra de búsqueda&quot;">​</a></h3><ul><li><strong>Ancho de la barra (Píxeles)</strong>: Rango <code>300–1200px</code>, por defecto <code>570px</code>.</li><li><strong>Alto de la barra (Píxeles)</strong>: Rango <code>45–120px</code>, por defecto <code>60px</code>. Este valor escala proporcionalmente el tamaño de los iconos, el alto de fila y la tipografía para mantener la armonía visual.</li><li><strong>Mostrar reloj en la barra de búsqueda</strong>: Sustituye el texto de sugerencia por la fecha y hora actuales cuando la barra está vacía. Desaparece al empezar a escribir.</li><li><strong>Abrir ventana principal al pulsar de nuevo el atajo</strong>: Si la Ventana rápida ya está abierta, pulsar de nuevo su atajo transfiere la búsqueda activa a la Ventana principal.</li><li><strong>Bloquear posición</strong>: Evita que la barra se mueva accidentalmente al arrastrarla con el ratón.</li><li><strong>Restablecer diseño</strong>: Restaura todas las propiedades de diseño a sus valores predeterminados.</li></ul><h3 id="prioridad-de-tipos-de-resultado-y-activadores" tabindex="-1">Prioridad de tipos de resultado y activadores <a class="header-anchor" href="#prioridad-de-tipos-de-resultado-y-activadores" aria-label="Permalink to &quot;Prioridad de tipos de resultado y activadores&quot;">​</a></h3><ul><li><strong>Lista de ordenación de prioridades</strong>: Arrastra los controles para cambiar la precedencia de aplicaciones, ajustes, archivos y extensiones de plugins.</li><li><strong>Carácter activador exclusivo</strong>: Asigna un prefijo de un solo carácter (p. ej. <code>;</code> para Filtros de archivos) para aislar las búsquedas a ese tipo concreto.</li></ul><h2 id="_3-ventana-de-busqueda-principal" tabindex="-1">3. Ventana de búsqueda principal <a class="header-anchor" href="#_3-ventana-de-busqueda-principal" aria-label="Permalink to &quot;3. Ventana de búsqueda principal&quot;">​</a></h2><p>Configura las dimensiones predeterminadas y la vista de tabla para la ventana principal (<code>Ctrl+F</code>):</p><ul><li><strong>Ancho / Alto de la ventana (Píxeles)</strong>: Ancho <code>640–2000px</code> (por defecto <code>854px</code>), alto <code>400–1400px</code> (por defecto <code>480px</code>).</li><li><strong>Permitir solo una ventana principal</strong>: Al volver a abrir la ventana principal, enfoca la existente en lugar de duplicarla.</li><li><strong>Restablecer configuración de ventana</strong>: Vuelve a los tamaños predeterminados de fábrica.</li><li><strong>Orden de columnas en la tabla</strong>: Personaliza el orden de las columnas (Nombre, Ruta, Fecha de modificación, etc.).</li><li><strong>Orden de filtros en la barra lateral</strong>: Reordena las categorías laterales; cada una muestra en tiempo real el recuento de coincidencias activas.</li><li><strong>Orden de grupos del menú de acciones</strong>: Modifica la disposición de los grupos dentro del menú de acciones contextuales (<code>Ctrl+O</code>).</li></ul><h2 id="_4-ventana-de-vista-previa" tabindex="-1">4. Ventana de vista previa <a class="header-anchor" href="#_4-ventana-de-vista-previa" aria-label="Permalink to &quot;4. Ventana de vista previa&quot;">​</a></h2><ul><li><strong>Ancho / Alto de la vista previa (Píxeles)</strong>: Ancho <code>250–900px</code>, alto <code>250–1200px</code>.</li><li><strong>Restablecer vista previa</strong>: Devuelve el panel de QuickLook a sus proporciones estándar, manteniéndose siempre dentro de los límites visibles de la pantalla.</li></ul><h2 id="_5-navegacion-rapida" tabindex="-1">5. Navegación rápida <a class="header-anchor" href="#_5-navegacion-rapida" aria-label="Permalink to &quot;5. Navegación rápida&quot;">​</a></h2><ul><li><strong>Orden de proveedores</strong>: Reordena las secciones de nivel superior en el menú de Navegación rápida (Favoritos, Historial, Carpetas abiertas y marcadores de exploradores).</li></ul><h2 id="_6-vista-previa-y-miniaturas" tabindex="-1">6. Vista previa y miniaturas <a class="header-anchor" href="#_6-vista-previa-y-miniaturas" aria-label="Permalink to &quot;6. Vista previa y miniaturas&quot;">​</a></h2><ul><li><strong>Orden de proveedores de vista previa</strong>: Ajusta la precedencia entre los renderizadores multimedia internos y el puente externo de QuickLook.</li><li><strong>Orden de proveedores de miniaturas</strong>: Ajusta la prioridad de los componentes encargados de extraer iconos y miniaturas de archivos.</li></ul>',19)])])}const m=e(n,[["render",s]]);export{g as __pageData,m as default};
